<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Common\Infrastructure\Driven;

use DateTimeImmutable;
use Override;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;
use Civi\Lughauth\Features\Notification\Outbox\Application\Usecase\Enqueue\EnqueueNotificationCommand;
use Civi\Lughauth\Features\Notification\Outbox\Application\Usecase\Enqueue\EnqueueNotificationUsecase;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\PasswordRecoveryMailGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\UserRegistrationMailGateway;

class OAuthMailAdapter implements PasswordRecoveryMailGateway, UserRegistrationMailGateway
{
    public function __construct(
        private readonly EnqueueNotificationUsecase $enqueue,
    ) {
    }

    #[Override]
    public function sendRegistrationVerification(
        string $toEmail,
        string $userName,
        TenantRef $tenant,
        string $activateUrl,
    ): void {
        $this->enqueue->enqueue(new EnqueueNotificationCommand(
            templateCode: 'user.register',
            channel: TemplateChannelOptions::MAIL,
            recipient: $toEmail,
            tenant: $tenant,
            variables: [
                'user'     => ['name' => $userName],
                'activate' => ['url' => $activateUrl],
            ],
            urgent: true,
        ));
    }

    #[Override]
    public function sendPasswordRecovery(
        string $toEmail,
        string $userName,
        TenantRef $tenant,
        string $recoveryUrl,
        DateTimeImmutable $expiresAt
    ): void {
        $this->enqueue->enqueue(new EnqueueNotificationCommand(
            templateCode: 'user.recover',
            channel: TemplateChannelOptions::MAIL,
            recipient: $toEmail,
            tenant: $tenant,
            variables: [
                'user'    => ['name' => $userName],
                'recover' => ['url' => $recoveryUrl, 'expires' => $expiresAt->format('Y-m-d H:i')],
            ],
            urgent: true,
        ));
    }
}
